namespace rb_tree_impl {

/**
 * @brief Color enum for Red-Black tree nodes.
 * 
 * A Red-Black tree is a self-balancing binary search tree.
 * Each node is either red or black.
 * 
 * Properties:
 * 1. Every node is either red or black.
 * 2. The root is black.
 * 3. All leaves (NIL) are black.
 * 4. If a node is red, then both its children are black.
 * 5. For each node, all paths from the node to descendant leaves contain the same number of black nodes.
 */
enum class Color {
    RED,    // Red color
    BLACK   // Black color
};

/**
 * @brief Returns the string representation of a Color.
 * @param c The color to convert.
 * @return A const char* string representing the color.
 */
inline const char* color_to_string(Color c) {
    switch (c) {
        case Color::RED:   return "RED";
        case Color::BLACK: return "BLACK";
        default:           return "UNKNOWN";
    }
}

